import{_ as t,o,c as d,a2 as r}from"./chunks/framework.uw_ZoRon.js";const h=JSON.parse('{"title":"Host ABI reference","description":"","frontmatter":{},"headers":[],"relativePath":"deep-dive/host-abi-reference.md","filePath":"deep-dive/host-abi-reference.md"}'),a={name:"deep-dive/host-abi-reference.md"};function s(c,e,n,i,l,p){return o(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="host-abi-reference" tabindex="-1">Host ABI reference <a class="header-anchor" href="#host-abi-reference" aria-label="Permalink to &quot;Host ABI reference&quot;">​</a></h1><p>A RUSM guest reaches the runtime through the <strong><code>rusm:runtime</code> actor ABI</strong> — the Erlang <code>Process</code> API (self, send, receive, registry, introspection, kill, …), backed by thin calls into <code>rusm-otp</code>. The ABI comes in two equivalent shapes, one per artifact kind, plus the standard WASI interfaces.</p><h2 id="components-—-the-rusm-runtime-wit-actor-world-wasip2-p3" tabindex="-1">Components — the <code>rusm:runtime</code> WIT actor world (wasip2/p3) <a class="header-anchor" href="#components-—-the-rusm-runtime-wit-actor-world-wasip2-p3" aria-label="Permalink to &quot;Components — the `rusm:runtime` WIT actor world (wasip2/p3)&quot;">​</a></h2><p>A WASI <strong>component</strong> imports the <code>rusm:runtime/actor</code> interface (a real WIT world, bound with <code>wasmtime::component::bindgen!</code>), so a guest in any language calls typed functions. Several capabilities are <strong>sibling interfaces</strong> — platform <em>bridges</em> split out of the core: <code>rusm:runtime/{kv, log, pg, serve, streams}</code> (and the shared <code>types</code>); all are imported into the one <code>process</code> world:</p><table tabindex="0"><thead><tr><th>Function</th><th>Meaning</th></tr></thead><tbody><tr><td><code>own-pid() -&gt; pid</code></td><td>the calling process&#39;s own pid</td></tr><tr><td><code>send(to: pid, msg: list&lt;u8&gt;)</code></td><td>enqueue bytes into another process&#39;s mailbox</td></tr><tr><td><code>receive() -&gt; list&lt;u8&gt;</code></td><td><strong>async</strong> — park the fiber until a message arrives</td></tr><tr><td><code>receive-timeout(timeout-ms) -&gt; option&lt;list&lt;u8&gt;&gt;</code></td><td>like <code>receive</code>, but gives up after a deadline — Erlang&#39;s <code>receive … after</code> (heartbeats, deadlines)</td></tr><tr><td><code>stash(msg) / unstash()</code></td><td>set the just-received message aside (keeping its host-side metadata) while awaiting a different one, then return everything stashed to the front of the mailbox — the host primitive behind the SDKs&#39; selective <code>call</code> (Erlang&#39;s selective <code>receive</code>); host-side so per-message metadata survives the deferral</td></tr><tr><td><code>list-processes() -&gt; list&lt;pid&gt;</code></td><td>all live pids</td></tr><tr><td><code>info(pid) -&gt; option&lt;process-info&gt;</code></td><td>links, monitors, names, label, mailbox depth, trap-exit</td></tr><tr><td><code>is-alive(pid) -&gt; bool</code> / <code>kill(pid) -&gt; bool</code></td><td>liveness / forced termination</td></tr><tr><td><code>register(name) / whereis(name) / unregister(name)</code></td><td>the named registry (1 name → 1 pid)</td></tr><tr><td><code>set-label(label)</code></td><td>a human-readable label for the observer</td></tr><tr><td><code>send-after(to, delay-ms, msg) -&gt; timer-id</code> / <code>cancel-timer(id) -&gt; bool</code></td><td>a delayed send (Erlang&#39;s <code>send_after</code>) and its cancellation</td></tr><tr><td><code>spawn(name) / monitor(pid) / supervise(…)</code></td><td>start, watch, and supervise child components (capability-gated)</td></tr><tr><td><code>spawn-from(name, source) -&gt; pid</code></td><td>spawn a <strong>dynamic</strong> runner-template instance from a runtime source (<code>inline:</code> / <code>kv:</code> / <code>url:</code>) under the template&#39;s declared profile — see <a href="/rusm/build-an-app/dynamic-js">dynamic JS</a> (capability-gated)</td></tr></tbody></table><h3 id="the-kv-interface-—-durable-storage-a-platform-bridge" tabindex="-1">The <code>kv</code> interface — durable storage (a platform bridge) <a class="header-anchor" href="#the-kv-interface-—-durable-storage-a-platform-bridge" aria-label="Permalink to &quot;The `kv` interface — durable storage (a platform bridge)&quot;">​</a></h3><p>Durable key-value storage is a sibling interface, <code>rusm:runtime/kv</code>, imported into the same <code>process</code> world (so a guest gets it alongside <code>actor</code>). It is authored as a <strong>bridge</strong> — one capability, owned end-to-end in <a href="https://github.com/archan937/rusm/tree/main/bridges/kv" target="_blank" rel="noreferrer"><code>bridges/kv/</code></a> (<code>bridge.wit</code> + <code>host.rs</code> + <code>guest.{rs,go,js}</code>) and materialized into every crate by <code>make sync-bridges</code>. Gated by the <strong>storage</strong> capability (default-deny).</p><table tabindex="0"><thead><tr><th>Function</th><th>Meaning</th></tr></thead><tbody><tr><td><code>kv.get(bucket, key) -&gt; option&lt;list&lt;u8&gt;&gt;</code></td><td>the stored value, or <code>none</code></td></tr><tr><td><code>kv.set(bucket, key, value)</code></td><td>store (overwrite)</td></tr><tr><td><code>kv.delete(bucket, key) -&gt; bool</code></td><td>remove; was-present</td></tr><tr><td><code>kv.exists(bucket, key) -&gt; bool</code></td><td>membership</td></tr><tr><td><code>kv.list(bucket) -&gt; list&lt;string&gt;</code></td><td>every key, sorted</td></tr></tbody></table><p>The ergonomic guest wrappers are unchanged — <code>rusm_rs::kv::bucket(..)</code>, the TS <code>kv.bucket(..)</code> global, Go&#39;s <code>OpenBucket(..)</code> — each backed by the Wasm-free <code>rusm-kv</code> crate over redb.</p><h3 id="the-streams-pg-and-log-interfaces-sibling-bridges" tabindex="-1">The <code>streams</code>, <code>pg</code>, and <code>log</code> interfaces (sibling bridges) <a class="header-anchor" href="#the-streams-pg-and-log-interfaces-sibling-bridges" aria-label="Permalink to &quot;The `streams`, `pg`, and `log` interfaces (sibling bridges)&quot;">​</a></h3><p>The same way <code>kv</code> split out, these capabilities are their own bridge interfaces — each owned end-to-end in <code>bridges/&lt;name&gt;/</code>, materialized by <code>make sync-bridges</code>, imported into the one <code>process</code> world. Same functions as before; only the interface they live in changed.</p><p><strong><code>rusm:runtime/streams</code></strong> — cross-process byte streams (Tokio back-pressured); <code>*-write</code>/ <code>*-read</code>/<code>*-accept</code> suspend the fiber rather than busy-spin. Guest: <code>rusm_rs::Stream</code>, the TS <code>Process.openStream</code>/<code>Stream</code>, Go&#39;s <code>OpenStream</code>.</p><table tabindex="0"><thead><tr><th>Function</th><th>Meaning</th></tr></thead><tbody><tr><td><code>stream-open(to: pid) -&gt; option&lt;stream-id&gt;</code></td><td>open a stream; the read end is delivered to <code>to</code></td></tr><tr><td><code>stream-write(handle, chunk) -&gt; bool</code> / <code>stream-close(handle)</code></td><td>write a chunk (back-pressured) / signal EOF</td></tr><tr><td><code>stream-accept() -&gt; stream-id</code> / <code>stream-read(handle) -&gt; option&lt;list&lt;u8&gt;&gt;</code></td><td>accept an incoming stream / read the next chunk (<code>none</code> = EOF)</td></tr></tbody></table><p><strong><code>rusm:runtime/pg</code></strong> — process-group tags (Erlang&#39;s <code>pg</code>), RUSM&#39;s pub/sub primitive (subscribe = <code>register-tag</code>, publish = <code>whereis-tag</code> + <code>send</code>). Guest: <code>rusm_rs::{register_tag, …}</code>, the TS <code>Process.registerTag</code>/etc., Go&#39;s <code>RegisterTag</code>/etc.</p><table tabindex="0"><thead><tr><th>Function</th><th>Meaning</th></tr></thead><tbody><tr><td><code>register-tag(tag)</code> / <code>unregister-tag(tag)</code></td><td>join / leave a tag (this process; unprivileged)</td></tr><tr><td><code>whereis-tag(tag) -&gt; list&lt;pid&gt;</code></td><td>live members of a tag</td></tr><tr><td><code>kill-tag(tag) -&gt; u32</code></td><td>terminate a whole group (count); gated by <strong>process-control</strong>, like <code>kill</code></td></tr></tbody></table><p><strong><code>rusm:runtime/log</code></strong> — platform logging (a polyfill bridge): a guest&#39;s standard logging — <code>console.*</code> (TS), the <code>log</code> crate (Rust), <code>log</code>/<code>slog</code> (Go) — routes to <code>log(level, message)</code>; the host stamps time, <code>component#pid</code>, and the severity colour, gated by the node <code>[log] level</code>.</p><p><strong><code>rusm:runtime/serve</code></strong> — per-connection serving controls for a WebSocket/SSE handler the host spawned for one accepted connection (a normal process gets <code>none</code>/<code>false</code>). Guest: the ergonomic <code>ws::Connection</code>/<code>sse::Stream</code> (RS), <code>web.Conn</code>/<code>web.Stream</code> (Go), <code>Process</code> methods (TS).</p><table tabindex="0"><thead><tr><th>Function</th><th>Meaning</th></tr></thead><tbody><tr><td><code>connection() -&gt; option&lt;connection-info&gt;</code></td><td>this handler&#39;s request context — method, path, captured <strong>route params</strong>, query, headers, remote address, negotiated subprotocol</td></tr><tr><td><code>ws-send-text(payload) / ws-close(code, reason)</code></td><td>a WebSocket handler&#39;s outbound <strong>text</strong> frame / <strong>close</strong> with status + reason (binary frames take the plain <code>send</code>→writer-process path)</td></tr><tr><td><code>sse-send(data, event?, id?, retry?) -&gt; bool</code></td><td>an SSE handler&#39;s <strong>rich event</strong> (<code>id</code>/<code>event</code>/<code>retry</code>); a plain <code>data:</code> event takes the <code>send</code>→writer path</td></tr></tbody></table><p>Composition is <strong>message passing</strong> (spawn instances, then <code>send</code>/<code>receive</code>/ <code>register</code>/<code>whereis</code>) — <em>not</em> WIT inter-component wiring, and no lattice. Standard <strong>WASI p2 and p3</strong> (<code>@0.2.0</code> and <code>@0.3.0</code> <code>wasi:cli</code>/<code>clocks</code>/<code>filesystem</code>/ <code>random</code>/<code>sockets</code>) are wired on the same component linker, gated by the process&#39;s capability profile.</p><h2 id="core-modules-—-the-raw-rusm-abi-wasip1" tabindex="-1">Core modules — the raw <code>rusm::*</code> ABI (wasip1) <a class="header-anchor" href="#core-modules-—-the-raw-rusm-abi-wasip1" aria-label="Permalink to &quot;Core modules — the raw `rusm::*` ABI (wasip1)&quot;">​</a></h2><p>A <code>wasm32-wasip1</code> <strong>core module</strong> can&#39;t pass a WIT <code>list&lt;u8&gt;</code>, so the same operations are flat imports under the <code>rusm</code> namespace that marshal through the guest&#39;s exported linear <code>memory</code> (pointer + length):</p><table tabindex="0"><thead><tr><th>Import</th><th>Signature</th></tr></thead><tbody><tr><td><code>own_pid</code> / <code>notify</code></td><td><code>() -&gt; i64</code> / <code>()</code> (the latter bumps the shared progress counter)</td></tr><tr><td><code>send</code></td><td><code>(to: i64, ptr: i32, len: i32)</code></td></tr><tr><td><code>receive</code></td><td><code>(ptr: i32, cap: i32) -&gt; i32</code> (async; returns the message length)</td></tr><tr><td><code>list_processes</code></td><td><code>(ptr: i32, cap: i32) -&gt; i32</code> (writes pids; returns the count)</td></tr><tr><td><code>is_alive</code> / <code>kill</code></td><td><code>(pid: i64) -&gt; i32</code></td></tr><tr><td><code>register</code> / <code>whereis</code> / <code>unregister</code></td><td><code>(ptr: i32, len: i32) -&gt; i32</code>/<code>i64</code>/<code>i32</code></td></tr><tr><td><code>set_label</code></td><td><code>(ptr: i32, len: i32)</code></td></tr><tr><td><code>stream_open</code></td><td><code>(to: i64) -&gt; i64</code> — open a byte stream to a process; returns a stream id</td></tr><tr><td><code>stream_write</code> / <code>stream_close</code></td><td><code>(id, ptr, len) -&gt; i32</code> (async, back-pressured) / <code>(id)</code></td></tr><tr><td><code>stream_accept</code> / <code>stream_read</code></td><td><code>() -&gt; i64</code> (async) / <code>(id, ptr, cap) -&gt; i32</code> (async; <code>-1</code> at EOF)</td></tr></tbody></table><p>Both shapes call the <em>same</em> <code>rusm-otp</code> operations; only the calling convention differs. Standard <strong>WASI preview1</strong> (clocks, random, env, stdio, scoped fs) is wired via <code>wasmtime_wasi::p1</code>, capability-gated.</p><h2 id="capabilities-default-deny" tabindex="-1">Capabilities (default-deny) <a class="header-anchor" href="#capabilities-default-deny" aria-label="Permalink to &quot;Capabilities (default-deny)&quot;">​</a></h2><p>Every grant maps onto standard WASI plus a <code>StoreLimiter</code> memory cap. Named profiles — <code>Sandboxed</code> (CPU + bounded heap only), <code>NetworkClient</code> (+ outbound network), <code>Trusted</code> (+ stdio, large heap, durable <strong>storage</strong>) — set defaults; a per-spawn <code>Capabilities</code> builder overrides them (<code>allow-spawn</code>, <code>allow-process-control</code>, <code>allow-storage</code>, …). The <strong>storage</strong> grant opens the node&#39;s embedded durable key-value store (the <code>kv</code> interface, backed by the Wasm-free <code>rusm-kv</code> crate over redb) — a sandboxed process has none. See <a href="/rusm/deep-dive/permissions-and-sandboxing">permissions &amp; sandboxing</a>.</p><h2 id="compatibility-—-standards-first-superpowers-opt-in" tabindex="-1">Compatibility — standards-first, superpowers opt-in <a class="header-anchor" href="#compatibility-—-standards-first-superpowers-opt-in" aria-label="Permalink to &quot;Compatibility — standards-first, superpowers opt-in&quot;">​</a></h2><p>RUSM is a <strong>standard WASI host</strong> (p1/p2/p3). A standard component or core module — including one built with <code>cargo component</code> or <a href="https://github.com/bytecodealliance/wstd" target="_blank" rel="noreferrer"><code>wstd</code></a> (the Bytecode Alliance&#39;s guest-side async std) — <strong>runs unchanged</strong>, to the extent it imports interfaces RUSM hosts. The <code>rusm:runtime</code> actor world is <strong>purely additive and opt-in</strong>: import it for the Erlang <code>Process</code> API, or ignore it and RUSM is just a fast, sandboxed WASI runtime. So there is no RUSM-specific convention to adopt, and nothing to make code non-portable.</p><p><code>wstd</code> itself is a <em>guest</em> library, not a host contract — &quot;wstd compatibility&quot; simply means hosting the standard WASI interfaces a wstd guest imports. Both pieces that make any standard component fully drop-in <strong>shipped in Phase 11</strong>:</p><ul><li><strong>Entrypoint:</strong> alongside RUSM&#39;s bare exported <code>run</code> func, stock <strong>command</strong> components that export <code>wasi:cli/run</code> run unchanged (<code>WasmRuntime::spawn_command</code>, which shares the same store-build path as the actor entrypoint).</li><li><strong><code>wasi:http</code>:</strong> RUSM hosts <code>wasi:http</code> (p2 + p3) — inbound for HTTP/SSE serving and a capability-gated, streaming <strong>outbound <code>fetch</code></strong> — so a wstd HTTP guest just works.</li></ul><h2 id="wire-protocol-node-↔-dashboard-repl" tabindex="-1">Wire protocol (node ↔ dashboard / REPL) <a class="header-anchor" href="#wire-protocol-node-↔-dashboard-repl" aria-label="Permalink to &quot;Wire protocol (node ↔ dashboard / REPL)&quot;">​</a></h2><p>Defined in <code>rusm-bench</code> <code>protocol.rs</code>, mirrored in the dashboard&#39;s <code>types.ts</code> (<code>serde</code> tagged, <code>snake_case</code>).</p><p>Server → client:</p><ul><li><code>hello { scenarios: ScenarioMeta[], profiles: ResourceProfileMeta[] }</code> — the scenario and resource-profile menus, sent on connect.</li><li><code>tick { frame: Frame }</code> — one sampled frame per tick.</li><li><code>error { message: string }</code> — a rejected command.</li></ul><p>Client → server:</p><ul><li><code>run { scenario: string }</code>, <code>stop</code></li><li><code>set_observer_detail { enabled: bool }</code></li><li><code>set_resource_profile { profile: string }</code> (<code>light</code> / <code>balanced</code> / <code>max</code>)</li></ul><p>A <code>Frame</code> = <code>{ scenario, running, uptime_ms, ops_per_sec, peak_concurrent, latency, throughput, observer, profile }</code>. Each <code>ScenarioMeta</code> carries a <code>unit</code> (<code>count</code> or <code>bytes</code>) so the dashboard formats throughput correctly.</p>',36)])])}const m=t(a,[["render",s]]);export{h as __pageData,m as default};
